"""Generate native navigation, linked cards, demo links, and image alternatives."""
from html import escape
from svg_canvas import ROOT, SETTINGS
from portfolio_sections import DATA, PROJECTS, day_label, language_rows, repository_date


def picture(name, alt, motion=False, theme=False, width=960):
    sources=[]
    if motion and theme:
        sources += [('(max-width: 600px) and (prefers-color-scheme: light) and (prefers-reduced-motion: reduce)',name+'-mobile-light-static'),('(prefers-color-scheme: light) and (prefers-reduced-motion: reduce)',name+'-light-static')]
    if motion:
        sources += [('(max-width: 600px) and (prefers-reduced-motion: reduce)',name+'-mobile-static'),('(prefers-reduced-motion: reduce)',name+'-static')]
    if theme:
        sources += [('(max-width: 600px) and (prefers-color-scheme: light)',name+'-mobile-light'),('(prefers-color-scheme: light)',name+'-light')]
    sources += [('(max-width: 600px)',name+'-mobile')]
    markup=['<picture>']
    for media,stem in sources:
        markup.append(f'  <source media="{media}" srcset="assets/generated/{stem}.svg">')
    markup += [f'  <img src="assets/generated/{name}.svg" width="{width}" alt="{escape(alt,quote=True)}">','</picture>']
    return '\n'.join(markup)


def readme():
    user=SETTINGS["username"]
    parts=["<!-- Generated by scripts/build_assets.py. Edit data/portfolio.json and data/projects.json. -->",
        picture("hero",SETTINGS["name"]+" — "+SETTINGS["identity"]+" / "+SETTINGS["role"]+". "+SETTINGS["typing_lines"][0],motion=True),SETTINGS["introduction"]]
    links=" · ".join(f"[{item['label']}]({item['url']})" for item in SETTINGS["links"])
    if SETTINGS.get("location"):
        links += " · "+SETTINGS["location"]
    parts.append(links)
    parts.append("[Toolkit](#toolkit) · [Projects](#selected-projects) · [Statistics](#github-statistics) · [Contribution history](#contribution-history) · [Recent activity](#recent-activity) · [Connect](#connect)")
    parts += ['## Toolkit',picture("stack","Technology groups: "+"; ".join(group["label"]+": "+", ".join(item["label"] for item in group["items"]) for group in SETTINGS["technology_groups"]))]
    if SETTINGS["currently_working_on"]:
        parts.append("**Currently working on:** "+"; ".join(SETTINGS["currently_working_on"]))
    if SETTINGS["currently_learning"]:
        parts.append("**Currently learning:** "+"; ".join(SETTINGS["currently_learning"]))
    parts.append("**Technical interests:** "+" · ".join(SETTINGS["interests"])+".")
    parts += ['## Selected projects',picture("projects-header",f"{len(PROJECTS)} selected learning projects. Each project card links to its source repository.")]
    for start in range(0,len(PROJECTS),2):
        row=['<p align="center">']
        for index,project in enumerate(PROJECTS[start:start+2],start):
            if index>start:
                row.append('&nbsp;')
            facts=DATA["featured"][project["repository"]]
            alt=f"{facts['name']}: {project['description']} Primary language: {facts['language']}. {facts['stars']} stars; {facts['forks']} forks. {repository_date(facts)}. Open repository."
            row += [f'<a href="{escape(facts["url"],quote=True)}">',f'<img src="assets/generated/project-{project["repository"].lower()}.svg" width="400" alt="{escape(alt,quote=True)}">','</a>']
        row.append('</p>');parts.append('\n'.join(row))
    demos=[f"[{project['title']} — live demo]({DATA['featured'][project['repository']]['demo_url']})" for project in PROJECTS if DATA['featured'][project['repository']]['demo_url']]
    if demos:
        parts.append("**Try a project:** "+" · ".join(demos))
    native=[]
    for project in PROJECTS:
        facts=DATA['featured'][project['repository']]
        native.append(f"- [{facts['name']}]({facts['url']}) — {project['description']}")
    parts.append('<details>\n<summary>Project descriptions and source links</summary>\n\n'+'\n'.join(native)+'\n\n</details>')
    parts += ['## GitHub statistics',picture("statistics",f"{DATA['contributions_since_joining']} contributions since joining in {DATA['joined_year']}, {DATA['public_repositories']} public repositories, {DATA['followers']} followers, {DATA['following']} following, {DATA['stars_on_original_repos']} stars on original public repositories, {DATA['public_pull_requests']} public pull requests, {DATA['public_issues']} public issues, and a {DATA['streak']['current']}-day current streak. Snapshot {day_label(DATA['updated_at'])} UTC."),picture("languages","Most-used languages by public source-code bytes: "+", ".join(f"{name} {100*count/sum(DATA['languages'].values()):.1f}%" for name,count in language_rows())+". Excludes forks and generated profile code; not a proficiency rating.")]
    history=' · '.join(f"[{item['year']}: {item['contributions']}](https://github.com/{user}?tab=overview&from={item['year']}-01-01&to={item['year']}-12-31)" for item in DATA['contributions_by_year'])
    parts += ['## Contribution history',picture("calendar",f"{DATA['contributions_last_year']} contributions in the last year; {DATA['active_days_in_grid']} active days and longest streak of {DATA['streak']['longest_in_grid']} days in the displayed calendar. Real GitHub intensity levels with month and weekday labels.",motion=True,theme=True),"**Contributions by year:** "+history,"[Open GitHub contribution history](https://github.com/"+user+"?tab=overview) · [Static calendar](assets/generated/calendar-static.svg)"]
    event_links=[f"- {item['created_at'][:10]} — [{item['summary']} · {item['repository']}]({item['url']})" for item in DATA['recent_events']]
    updates=[f"- {item['pushed_at'][:10]} — [{item['repository']}]({item['url']})" for item in DATA['recent_updates']]
    parts += ['## Recent activity',picture("recent","Latest public repository push dates and dated public events. The event feed is limited to the latest 30 days and may be delayed. Native source links follow."),'<details>\n<summary>Open activity and repository links</summary>\n\n**Repository updates**\n\n'+'\n'.join(updates)+'\n\n**Public events returned in the last 30 days**\n\n'+ ('\n'.join(event_links) if event_links else 'No public events returned in this window.')+'\n\n</details>','## Connect',picture("footer","Let’s build something useful. Connect with "+SETTINGS['name']+" using the links below."),links]
    parts.append(f"<sub>Public GitHub snapshot · Updated {day_label(DATA['updated_at'])} UTC · Generated daily; GitHub may cache images.</sub>")
    (ROOT/'README.md').write_text('\n\n'.join(parts)+'\n',encoding='utf-8')
